  const create=(kind:FormKind,values:Record<string,string>={},editingId?:string)=>{setMessage('');const enriched={...values,...(editingId&&(kind==='dayTask'||kind==='entry')?{__category_manual:'1'}:{}),...(kind==='task'&&values.project_ids===undefined?{project_ids:data?.taskProjects.filter(x=>x.task_id===editingId).map(x=>x.project_id).join(',')||''}:{}),...(kind==='assignment'&&values.long_project_id===undefined?{long_project_id:data?.assignments.find(x=>x.id===editingId)?.long_project_id||''}:{}),...((kind==='assignment'||kind==='dayTask')&&values.priority===undefined?{priority:(kind==='assignment'?data?.assignments:data?.dayTasks)?.find(x=>x.id===editingId)?.priority||''}:{}),...(kind==='annual'&&values.status===undefined?{status:editingId&&data?.annualGoals.find(x=>x.id===editingId)?annualStatus(data.annualGoals.find(x=>x.id===editingId)!):'todo'}:{})};setChildPrompt(false);setForm({kind,values:data&&(kind==='entry'||kind==='dayTask')&&!editingId?applyLinkedCategory(data,kind,enriched):enriched,editingId,initial:JSON.stringify(enriched)});};
