  const focusTask=(taskId:string)=>{if(!data?.tasks.some(t=>t.id===taskId)){setMessage('该本轮待办已不存在');return;}setPoolRequest(null);setTaskPool('task');setFocusedTaskId(taskId);setPage('tasks');};
